/** The header carries its own checksum over itself, with the checksum field
 * read as spaces. A mismatch means the size fields cannot be trusted, which is
 * the only thing this reader takes from a header. */
function checksum(header) {
  let sum = 0;
  for (let index = 0; index < BLOCK; index += 1)
    sum += index >= 148 && index < 156 ? 32 : header[index];
  return sum;
}

